def expand(base_cards):
    lookup={c['id']:c for c in base_cards}
    added=[]
    keys=['id','parent','title','condition','input','process','output','data','invariant','failure','control','measure','test','tradeoff','open']
    for row in ROWS.splitlines():
        vals=row.split('|')
        assert len(vals)==len(keys),(vals[0],len(vals))
        c=dict(zip(keys,vals)); parent=lookup[c['parent']]
        for k in ['domain','goal','variables','resources','book_anchor','source_refs','source_relation']:
            c[k]=parent[k]
        c.update(type='mechanism',status='mapped_not_observed',provenance='analyst_recursive_expansion',
                 frame=parent['frame']+'; '+c['condition'],reopen=c['open'],evidence_status='proposed_test_not_run_on_real_system')
        # No copy of the parent's metric: the measurement must follow this smaller mechanism.
        c['metric_sketch']={**parent['metric_sketch'],'q':c['measure'],'domain':c['frame'],'conditions':c['condition'],
                          'data':c['data'],'method':c['test'],'limitation':c['tradeoff']+'; '+c['open'],
                          'binding':c['id']+' → '+c['process']}
        c['six_regions']={
            'meaning':c['invariant'],'domain':c['frame'],'mechanism':c['process']+'; failure: '+c['failure'],
            'evidence':c['test'],'operational':c['resources']+'; '+c['tradeoff'],'consequence':c['goal']+'; '+c['open']}
        lookup[c['id']]=c;added.append(c)
    return added
